import re
from taf.rfrl.utilities.robot.general import get_builtin_value
from taf.rfrl.utilities import tl_config


def get_possible_beamsets_configuration(bts_id=0, du_id=0, ru_id=0):
    """
    Get possible basic beamsets configuration, or it can be manually add in suite, using global robot variable
    :param bts_id:          BTS id - related to Test Line configuration. Default: 0
    :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :param ru_id:           position of RU in rus table from Test Line configuration.
    """
    configuration_mapping = {
        0: '1P',
        1: '2P',
        2: '3P',
    }
    number_of_ext = get_builtin_value("number_of_extensions")
    if not number_of_ext:
        number_of_extensions = tl_config.get_count_of_ru_extensions(bts_id, du_id, ru_id, 'GNB')
    else:
        number_of_extensions = int(number_of_ext)
    configuration = configuration_mapping[number_of_extensions]

    return _get_possible_beamsets(configuration=configuration)


def _get_possible_beamsets(configuration='1P'):
    all_possible_beam_sets = [
        'beamSetFR2_16_8_8_1P',
        'beamSetFR2_8_8_8_8_1P',
        'beamSetFR2_6_6_4_2P',
        'beamSetFR2_4_4_2_3P',
        'beamSetFR2_6_2_4P',
    ]
    _re_beam_set = re.compile(r'_{}$'.format(configuration))
    possible_beam_sets = []
    for beam_set in all_possible_beam_sets:
        if _re_beam_set.search(beam_set):
            possible_beam_sets.append(beam_set)

    return possible_beam_sets
